// Sourced Practice Leads
// Connected to your targeting filters (London / Regional Chartered Accountants)
const config = $('1. Configuration & Secrets').first().json;

const rawSourcedLeads = [
  {
    "business_name": "KP Tax Consultants Ltd",
    "phone": "+44 7861 690954",
    "website": "https://kptc.co.uk",
    "address": "Mayfair, London W1J",
